CREATE VIEW dbo.IV_Q$AVAL_COLH_CANA_USADA ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , ESTADO_GERAL, LATARIA_E_PINTURA, MOTOR___FUNCIONAMENT, MOTOR___VAZAMENTO_DE, MOTOR_VAZ_COMBUSTIVE, MOTOR_VAZ_AGUA, PARTE_ELETRICA___BAT, PARTE_ELET_PARTIDA, PAINEL_DE_INSTRUMENT, TRANSMISSAO___FUNCIO, TRANSMISSAO___VAZAME, SISTEMA_HIDRAULICO__, SISTEMA_DE_DIRECAO, ROLOS_DIVISORES, ROLOS_PICADORES, ELEVADOR___CONDICOES, ELEVADOR___TALISCAS, EXTRATOR_PRIMARIO, EXTRATOR_SECUNDARIO, CHASSI_DA_MAQUINA___, CABINE_DO_OPERADOR, NOTAL_GERAL_ATRIBUID, MATERIAL_RODANTE___S, MATERIAL_RODANTE___L, MATERIAL_RODANTE___R, MAT_ROD_ROL_INFERIOR, OBS_GERAIS, VALOR_PEDIDO_PELO_CL, VALOR_APURADO_NO_MER, VALOR_ATRIBUIDO_PARA, VALIDADE_DA_AVALIACA)     AS SELECT PES.SEQPESSOA, PES.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.ESTADO_GERAL, TABF.LATARIA_E_PINTURA, TABF.MOTOR___FUNCIONAMENT, TABF.MOTOR___VAZAMENTO_DE, TABF.MOTOR_VAZ_COMBUSTIVE, TABF.MOTOR_VAZ_AGUA, TABF.PARTE_ELETRICA___BAT, TABF.PARTE_ELET_PARTIDA, TABF.PAINEL_DE_INSTRUMENT, TABF.TRANSMISSAO___FUNCIO, TABF.TRANSMISSAO___VAZAME, TABF.SISTEMA_HIDRAULICO__, TABF.SISTEMA_DE_DIRECAO, TABF.ROLOS_DIVISORES, TABF.ROLOS_PICADORES, TABF.ELEVADOR___CONDICOES, TABF.ELEVADOR___TALISCAS, TABF.EXTRATOR_PRIMARIO, TABF.EXTRATOR_SECUNDARIO, TABF.CHASSI_DA_MAQUINA___, TABF.CABINE_DO_OPERADOR, TABF.NOTAL_GERAL_ATRIBUID, TABF.MATERIAL_RODANTE___S, TABF.MATERIAL_RODANTE___L, TABF.MATERIAL_RODANTE___R, TABF.MAT_ROD_ROL_INFERIOR, TABF.OBS_GERAIS, TABF.VALOR_PEDIDO_PELO_CL, TABF.VALOR_APURADO_NO_MER, TABF.VALOR_ATRIBUIDO_PARA, TABF.VALIDADE_DA_AVALIACA    FROM  IV_Q_AVAL_COLH_CANA_USADA TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA PES ON PES.SEQPESSOA = QST.SEQPESSOA 